// TrustyFile checksum validators. Generated by scripts/build_guides.py —
// mirrors src/modules/content.py; both are held to tests/fixtures/checksum_vectors.json.
(function (root) {
  'use strict';
  var LA_POSTE_SIREN = '356000000';
  var IBAN_LENGTHS = { AT: 20, BE: 16, CH: 21, DE: 22, ES: 24, FR: 27, GB: 22, IE: 22,
                       IT: 27, LU: 20, MC: 27, NL: 18, PL: 28, PT: 25 };

  function stripSeparators(text) { return String(text == null ? '' : text).replace(/[\s.\-]/g, ''); }

  // Luhn as content.py applies it: for 14 digits the doubled positions are the
  // even indexes from the left (0, 2, ... 12); for 9 digits the odd ones (1, 3, 5, 7).
  function luhnOk(digits, doubleEvenIndexes) {
    var total = 0;
    for (var i = 0; i < digits.length; i++) {
      var d = digits.charCodeAt(i) - 48;
      if ((i % 2 === 0) === doubleEvenIndexes) { d *= 2; if (d > 9) { d -= 9; } }
      total += d;
    }
    return total % 10 === 0;
  }
  function digitSum(digits) {
    var s = 0;
    for (var i = 0; i < digits.length; i++) { s += digits.charCodeAt(i) - 48; }
    return s;
  }
  // Remainder of a long decimal string divided by 97, digit by digit (no BigInt needed).
  function mod97(digits) {
    var m = 0;
    for (var i = 0; i < digits.length; i++) { m = (m * 10 + (digits.charCodeAt(i) - 48)) % 97; }
    return m;
  }

  function sirenCheck(text) {
    var siren = stripSeparators(text);
    if (!/^\d{9}$/.test(siren)) { return { ok: false, reason: 'format', value: siren }; }
    var ok = luhnOk(siren, false);
    // French VAT key, as content.py's validate_french_vat computes it.
    var key = (12 + 3 * mod97(siren)) % 97;
    return { ok: ok, reason: ok ? null : 'checksum', value: siren, vatKey: (key < 10 ? '0' : '') + key };
  }

  function siretCheck(text) {
    var siret = stripSeparators(text);
    if (!/^\d{14}$/.test(siret)) { return { ok: false, reason: 'format', value: siret }; }
    var luhn = luhnOk(siret, true);
    var laPoste = siret.indexOf(LA_POSTE_SIREN) === 0;
    var ok = luhn || (laPoste && digitSum(siret) % 5 === 0);
    return { ok: ok, reason: ok ? null : 'checksum', value: siret,
             siren: siret.slice(0, 9), nic: siret.slice(9), laPoste: laPoste && ok && !luhn };
  }

  // French RIB key: bank (5) branch (5) account (11) key (2). Letters in the
  // account map to digits (A,J=1 B,K,S=2 ... I,R,Z=9); key = 97 - (BGC x 100 mod 97).
  function ribKeyOk(bban) {
    var account = bban.slice(10, 21).toUpperCase().replace(/[A-Z]/g, function (ch) {
      var n = ch.charCodeAt(0) - 64;
      return String(n < 10 ? n : (n < 19 ? n - 9 : n - 17));
    });
    var remainder = (mod97(bban.slice(0, 10) + account) * 100) % 97;
    return (97 - remainder) === parseInt(bban.slice(21, 23), 10);
  }

  function ibanCheck(text) {
    var iban = stripSeparators(text).toUpperCase();
    if (!/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(iban)) { return { ok: false, reason: 'format', value: iban }; }
    var rearranged = iban.slice(4) + iban.slice(0, 4);
    var numeric = '';
    for (var i = 0; i < rearranged.length; i++) {
      var c = rearranged.charCodeAt(i);
      numeric += c >= 65 ? String(c - 55) : rearranged.charAt(i);   // A=10 ... Z=35
    }
    var ok = mod97(numeric) === 1;
    var country = iban.slice(0, 2);
    var expected = IBAN_LENGTHS[country] || null;
    return { ok: ok, reason: ok ? null : 'checksum', value: iban, country: country,
             expectedLength: expected, lengthOk: expected ? iban.length === expected : null,
             formatted: iban.replace(/(.{4})/g, '$1 ').trim(),
             ribKeyOk: (country === 'FR' && iban.length === 27) ? ribKeyOk(iban.slice(4)) : null };
  }

  // French VAT number: FR + two-digit key + SIREN; key = (12 + 3 x (SIREN mod 97)) mod 97,
  // as content.py's validate_french_vat computes it. Keys with letters (another
  // algorithm) are a format failure here, never a guess.
  function vatCheck(text) {
    var vat = stripSeparators(text).toUpperCase();
    if (!/^FR\d{11}$/.test(vat)) { return { ok: false, reason: 'format', value: vat }; }
    var key = vat.slice(2, 4), siren = vat.slice(4);
    var sirenOk = luhnOk(siren, false);
    var expected = (12 + 3 * mod97(siren)) % 97;
    var expectedKey = (expected < 10 ? '0' : '') + expected;
    var ok = sirenOk && key === expectedKey;
    return { ok: ok, reason: ok ? null : 'checksum', value: vat, key: key, siren: siren,
             sirenOk: sirenOk, expectedKey: expectedKey };
  }

  // French social security number (NIR): 13 characters + 2-digit key; key = 97 - (13 digits mod 97),
  // Corsica's 2A / 2B read as 19 / 18 (INSEE). Mirrors content.py's is_valid_nir.
  function nirCheck(text) {
    var nir = stripSeparators(text).toUpperCase();
    if (!/^[1-8]\d{4}(?:\d{2}|2A|2B)\d{8}$/.test(nir)) { return { ok: false, reason: 'format', value: nir }; }
    var dept = nir.slice(5, 7);
    var digits = nir.slice(0, 5) + (dept === '2A' ? '19' : (dept === '2B' ? '18' : dept)) + nir.slice(7, 13);
    var expected = 97 - mod97(digits);
    var ok = expected === parseInt(nir.slice(13, 15), 10);
    return { ok: ok, reason: ok ? null : 'checksum', value: nir, sex: nir.charAt(0),
             year: nir.slice(1, 3), month: nir.slice(3, 5), dept: dept,
             expectedKey: (expected < 10 ? '0' : '') + expected,
             formatted: nir.replace(/^(.)(..)(..)(..)(...)(...)(..)$/, '$1 $2 $3 $4 $5 $6 $7') };
  }

  // RIB key of bank (5) + branch (5) + account (11). Mirrors content.py's rib_key.
  function ribKey(bga) {
    var account = bga.slice(10).replace(/[A-Z]/g, function (ch) {
      var n = ch.charCodeAt(0) - 64;
      return String(n < 10 ? n : (n < 19 ? n - 9 : n - 17));
    });
    return 97 - (mod97(bga.slice(0, 10) + account) * 100) % 97;
  }
  // French IBAN for a full BBAN (23 characters): check digits = 98 - (BBAN + "FR00" mod 97).
  function frenchIban(bban) {
    var numeric = (bban + 'FR00').replace(/[A-Z]/g, function (ch) { return String(ch.charCodeAt(0) - 55); });
    var check = 98 - mod97(numeric);
    return ('FR' + (check < 10 ? '0' : '') + check + bban).replace(/(.{4})/g, '$1 ').trim();
  }
  // French RIB: 23 characters is checked (is_valid_rib); 21 (no key yet) gets its key computed.
  function ribCheck(text) {
    var rib = stripSeparators(text).toUpperCase();
    var m = /^(\d{5})(\d{5})([0-9A-Z]{11})(\d{2})?$/.exec(rib);
    if (!m) { return { ok: false, reason: 'format', value: rib }; }
    var key = ribKey(m[1] + m[2] + m[3]);
    var keyText = (key < 10 ? '0' : '') + key;
    var full = m[1] + m[2] + m[3] + keyText;
    var base = { value: rib, bank: m[1], branch: m[2], account: m[3], expectedKey: keyText, iban: frenchIban(full) };
    if (!m[4]) { base.ok = false; base.reason = 'compute'; return base; }
    base.ok = m[4] === keyText;
    base.reason = base.ok ? null : 'checksum';
    base.key = m[4];
    return base;
  }

  // ICAO 9303 check digit: weights 7-3-1, A=10 ... Z=35, '<' = 0.
  function mrzDigit(data) {
    var total = 0, weights = [7, 3, 1];
    for (var i = 0; i < data.length; i++) {
      var c = data.charCodeAt(i);
      var v = c >= 65 ? c - 55 : (c >= 48 && c <= 57 ? c - 48 : 0);
      total += v * weights[i % 3];
    }
    return total % 10;
  }
  // MRZ of a passport (TD3), an ID card (TD1, TD2) or the French card of 1988-2021,
  // told apart by length once whitespace is removed. Mirrors identity.py's mrz_text_checks.
  function mrzCheck(text) {
    var mrz = String(text == null ? '' : text).replace(/\s/g, '').toUpperCase();
    if (!/^[A-Z0-9<]+$/.test(mrz)) { return { ok: false, reason: 'format', value: mrz }; }
    var fmt, l1, l2, f, birth, expiry = null;
    if (mrz.length === 88) {
      fmt = 'TD3'; l1 = mrz.slice(0, 44); l2 = mrz.slice(44);
      f = [['number', l2.slice(0, 9), l2[9]], ['birth', l2.slice(13, 19), l2[19]],
           ['expiry', l2.slice(21, 27), l2[27]], ['personal', l2.slice(28, 42), l2[42]],
           ['composite', l2.slice(0, 10) + l2.slice(13, 20) + l2.slice(21, 43), l2[43]]];
      birth = l2.slice(13, 19); expiry = l2.slice(21, 27);
    } else if (mrz.length === 90) {
      fmt = 'TD1'; l1 = mrz.slice(0, 30); l2 = mrz.slice(30, 60);
      f = [['number', l1.slice(5, 14), l1[14]], ['birth', l2.slice(0, 6), l2[6]],
           ['expiry', l2.slice(8, 14), l2[14]],
           ['composite', l1.slice(5, 30) + l2.slice(0, 7) + l2.slice(8, 15) + l2.slice(18, 29), l2[29]]];
      birth = l2.slice(0, 6); expiry = l2.slice(8, 14);
    } else if (mrz.length === 72 && mrz.indexOf('IDFRA') === 0) {
      fmt = 'FR1988'; l1 = mrz.slice(0, 36); l2 = mrz.slice(36);
      f = [['number', l2.slice(0, 12), l2[12]], ['birth', l2.slice(27, 33), l2[33]],
           ['composite', l1 + l2.slice(0, 35), l2[35]]];
      birth = l2.slice(27, 33);
    } else if (mrz.length === 72) {
      fmt = 'TD2'; l1 = mrz.slice(0, 36); l2 = mrz.slice(36);
      f = [['number', l2.slice(0, 9), l2[9]], ['birth', l2.slice(13, 19), l2[19]],
           ['expiry', l2.slice(21, 27), l2[27]],
           ['composite', l2.slice(0, 10) + l2.slice(13, 20) + l2.slice(21, 35), l2[35]]];
      birth = l2.slice(13, 19); expiry = l2.slice(21, 27);
    } else {
      return { ok: false, reason: 'format', value: mrz };
    }
    var checks = f.map(function (x) {
      var c = x[2], d = mrzDigit(x[1]);
      return { field: x[0], ok: c === '<' ? d === 0 : (/^\d$/.test(c) && d === +c) };
    });
    var ok = checks.every(function (c) { return c.ok; });
    return { ok: ok, reason: ok ? null : 'checksum', value: mrz, format: fmt, checks: checks,
             birth: birth, expiry: expiry };
  }

  var api = { ibanCheck: ibanCheck, siretCheck: siretCheck, sirenCheck: sirenCheck, vatCheck: vatCheck,
              nirCheck: nirCheck, ribCheck: ribCheck, mrzCheck: mrzCheck };
  root.TFChecks = api;
  if (typeof module !== 'undefined' && module.exports) { module.exports = api; }
})(typeof window !== 'undefined' ? window : this);
